import{_ as s,o as a,c as n}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse(`{"title":"Page 32 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"32","title":"Page 32 | Home","prev":"/page/31/","next":"/page/33/","posts":[{"title":"JavaScript处理二进制数据","url":"/posts/2014-11-23-javascript-binary/","date":"2014-11-23 14:30","tags":["js"],"html":"<p>最近在开发扩展的时候遇到需要获取 MP3 数据并且直接交给其它接口处理的问题,但是使用 JQuery 的 AJAX 进行\\n获取数据的时候已经把数据进行了编码,毕竟默认都是处理文本数据.<br>\\n但是我需要的是二进制数据并且进行 Base64 编码方便进行传输,因为 Base64 编码的值全是可打印字符.\\nBase64 常用于在通常处理文本数据的场合,表示、传输、存储一些二进制数据.</p>\\n<h2 id=\\"二进制数据转换成-base64-编码\\" tabindex=\\"-1\\">二进制数据转换成 Base64 编码 <a class=\\"header-anchor\\" href=\\"#二进制数据转换成-base64-编码\\" aria-label=\\"Permalink to &quot;二进制数据转换成 Base64 编码&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>于是便找到了一个非常有用的 MDN 的文档<a href=\\"https://developer.mozilla.org/en-US/docs/Web/API/XMLHttpRequest/Sending_and_Receiving_Binary_Data\\" target=\\"_blank\\" rel=\\"noreferrer\\">Sending and Receiving Binary Data</a><br>\\n不过稍作修改:</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> oReq </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> XMLHttpRequest</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">oReq.</span><span style=\\"color:#6F42C1\\">open</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'GET'</span><span style=\\"color:#24292E\\">, request.data, </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">oReq.responseType </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'blob'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">oReq.</span><span style=\\"color:#6F42C1\\">onload</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> function</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">oEvent</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  var</span><span style=\\"color:#24292E\\"> blob </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> oReq.response;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  var</span><span style=\\"color:#24292E\\"> reader </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> FileReader</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  reader.</span><span style=\\"color:#6F42C1\\">onload</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> function</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">readerEvt</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    var</span><span style=\\"color:#24292E\\"> binaryString </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> readerEvt.target.result;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">    // console.log(binaryString);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    var</span><span style=\\"color:#24292E\\"> testdata </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#6F42C1\\"> btoa</span><span style=\\"color:#24292E\\">(binaryString);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    var</span><span style=\\"color:#24292E\\"> data </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      method: </span><span style=\\"color:#032F62\\">'getAudio'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      data: </span><span style=\\"color:#032F62\\">'data:audio/mp3;base64,'</span><span style=\\"color:#D73A49\\"> +</span><span style=\\"color:#6F42C1\\"> btoa</span><span style=\\"color:#24292E\\">(binaryString)</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    port.</span><span style=\\"color:#6F42C1\\">postMessage</span><span style=\\"color:#24292E\\">(data);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  reader.</span><span style=\\"color:#6F42C1\\">readAsBinaryString</span><span style=\\"color:#24292E\\">(blob);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">oReq.</span><span style=\\"color:#6F42C1\\">send</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">null</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br></div></div><p>设置 responseType 为<a href=\\"https://developer.mozilla.org/en/docs/Web/API/Blob\\" target=\\"_blank\\" rel=\\"noreferrer\\">Blob</a>\\n然后使用 FileReader 作为二进制数据读取,再使用 btoa 转码成 Base64 进行传输.</p>\\n<p>还有一种是读取需要上传的文件进行处理的方式和通过 AJAX 获取的方式差不多,代码在<a href=\\"http://jsfiddle.net/eliseosoto/JHQnk/\\" target=\\"_blank\\" rel=\\"noreferrer\\">这里</a>.使用 Base64 编码的好处是在需要二进制数据的地方,例如图片和音频,我们可以使用 Base64 编码进行替换获取这些资源的 URL\\n可以减少 HTTP 请求,也可以做转发,我之所以有这个处理二进制数据的需求就是因为开发的一个插件无法在 HTTPS 页面上获取 HTTP 资源,\\n便通过 background js 进行获取数据然后 Base64 编码传输给 content js 进行使用.</p>\\n<h2 id=\\"base64-数据转换为-arraybuffer\\" tabindex=\\"-1\\">Base64 数据转换为 ArrayBuffer <a class=\\"header-anchor\\" href=\\"#base64-数据转换为-arraybuffer\\" aria-label=\\"Permalink to &quot;Base64 数据转换为 ArrayBuffer&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>有时候需要把传入的二进制数据转换成 ArrayBuffer 进行处理就需要转换了</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> data </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#6F42C1\\"> atob</span><span style=\\"color:#24292E\\">(base64String);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> dataView </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> Uint8Array</span><span style=\\"color:#24292E\\">(data.</span><span style=\\"color:#005CC5\\">length</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">for</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> i </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">; i </span><span style=\\"color:#D73A49\\">&#x3C;</span><span style=\\"color:#24292E\\"> data.</span><span style=\\"color:#005CC5\\">length</span><span style=\\"color:#24292E\\">; </span><span style=\\"color:#D73A49\\">++</span><span style=\\"color:#24292E\\">i) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  dataView[i] </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> data.</span><span style=\\"color:#6F42C1\\">charCodeAt</span><span style=\\"color:#24292E\\">(i);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> arrayBuffer </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> dataView.buffer;</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br></div></div><p>今天暂时就写这么多吧,期末考试看书好累,头脑都不太清醒了. QAQ</p>\\n"},{"title":"扇贝单词助手发布","url":"/posts/2014-10-30-shanbay-helper/","date":"2014-10-30 18:30","tags":["notes"],"html":"<p>最近受菊苣<a href=\\"https://plus.google.com/u/0/+RoyBinux/\\" target=\\"_blank\\" rel=\\"noreferrer\\">binux</a>的要求,希望能开发一款扇贝网的<a href=\\"https://chrome.google.com/webstore/detail/shanbayhelper/mbekldhkbpihlaogjpclihoobhoakcic\\" target=\\"_blank\\" rel=\\"noreferrer\\">单词助手</a>,可以标记任意页面上已经背过的单词.项目源码在<a href=\\"https://github.com/acgotaku/ShanBayHelper\\" target=\\"_blank\\" rel=\\"noreferrer\\">Github</a>.\\n然后我就趁着国庆就开坑了,binux 也给了我很多参考资料.因为之前也开发过 Chrome 的扩展,所以对 Chrome 提供的 API 比较熟悉.这里就介绍下使用的相关的 JavaScript 的知识吧~</p>\\n<h2 id=\\"promise\\" tabindex=\\"-1\\">Promise <a class=\\"header-anchor\\" href=\\"#promise\\" aria-label=\\"Permalink to &quot;Promise&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Promise 是用来处理大量的异步操作,因为异步操作不能直接 return 返回值,必须进行回调.所以就会导致很多异步操作在一起不断的进行嵌套,这样实在是很不优雅的代码书写方式.代码首先是用来给人读的,其次才是可以运行.使用 Promise 就可以把多个异步操作的返回值以数组的形式返回来,然后再进行回调.语言描述不好,还是上例子吧.</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> get_cookie</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">site</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">name</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#005CC5\\"> Promise</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">resolve</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">reject</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    chrome.cookies.</span><span style=\\"color:#6F42C1\\">get</span><span style=\\"color:#24292E\\">({ url: site, name: name }, </span><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">cookies</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      if</span><span style=\\"color:#24292E\\"> (cookies) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        var</span><span style=\\"color:#24292E\\"> data </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> cookies.name </span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#032F62\\"> '='</span><span style=\\"color:#D73A49\\"> +</span><span style=\\"color:#24292E\\"> cookies.value;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">        resolve</span><span style=\\"color:#24292E\\">(data);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      } </span><span style=\\"color:#D73A49\\">else</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">        reject</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br></div></div><p>Chrome 的 API 全部是异步操作,所以我一开始使用 return 的时候并没有得到值.把回调函数封装到一个 Promise 对象里面,然后传入两个参数 resolve,reject 分别代表异步操作成功执行或失败需要调用的函数.</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> site1 </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'http://pan.baidu.com/'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> name1 </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'BDUSS'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> site2 </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'http://pcs.baidu.com/'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> name2 </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'pcsett'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">Promise</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">all</span><span style=\\"color:#24292E\\">([</span><span style=\\"color:#6F42C1\\">get_cookie</span><span style=\\"color:#24292E\\">(site1, name1), </span><span style=\\"color:#6F42C1\\">get_cookie</span><span style=\\"color:#24292E\\">(site2, name2)]).</span><span style=\\"color:#6F42C1\\">then</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  function</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">value</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    console.</span><span style=\\"color:#6F42C1\\">log</span><span style=\\"color:#24292E\\">(value);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  function</span><span style=\\"color:#24292E\\"> () {}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br></div></div><p>这里我们需要调用两次异步操作,一般情况的话需要函数嵌套,但是使用 Promise 对象的话,只需要在 then 里面需要写上 resolve 和 reject 需要的执行函数,\\n传入的 value 就是两次异步操作的返回值数组.然后就可以进行相关的处理.代码就变得清晰有条理.</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://developer.mozilla.org/en-US/docs/Mozilla/JavaScript_code_modules/Promise.jsm/Promise\\" target=\\"_blank\\" rel=\\"noreferrer\\">Promise 文档</a></p>\\n<p><a href=\\"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Promise/all\\" target=\\"_blank\\" rel=\\"noreferrer\\">Promise.all</a></p>\\n"},{"title":"计算机中的字节序问题","url":"/posts/2014-09-30-computer-endian/","date":"2014-09-30 12:30","tags":["endian"],"html":"<p>计算机字节序这个问题,最近被老师反复提到.我也在本科阶段折腾交叉编译的时候遇到过.并且这个问题貌似也是面试的时候一个常见问题,所以还是写下来比较好.</p>\\n<p>字节序顾名思义就是计算机中字节的存储顺序.目前最常见的就是大端字节序和小端字节序.貌似百科里面又有一个中端字节序...(不过确实很少见)</p>\\n<h2 id=\\"大端字节序\\" tabindex=\\"-1\\">大端字节序 <a class=\\"header-anchor\\" href=\\"#大端字节序\\" aria-label=\\"Permalink to &quot;大端字节序&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>按照最高位字节(包含最高位,即 MSB,的字节)至最低位字节(包含最低位,即 LSB,的字节)的顺序,存放在连续的地址中.</p>\\n<p>采用这种机制的处理器有 IBM3700 系列,和绝大多数的 RISC 处理(我的路由器就是)</p>\\n<h2 id=\\"小端字节序\\" tabindex=\\"-1\\">小端字节序 <a class=\\"header-anchor\\" href=\\"#小端字节序\\" aria-label=\\"Permalink to &quot;小端字节序&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>按照最低位字节(包含 LSB 的字节)至最高位字节(包含 MSB 的字节)的顺序,存放在连续的地址中.</p>\\n<p>采用这种机制的处理器最常见的就是 Intel 系列处理器</p>\\n<h2 id=\\"判断字节序\\" tabindex=\\"-1\\">判断字节序 <a class=\\"header-anchor\\" href=\\"#判断字节序\\" aria-label=\\"Permalink to &quot;判断字节序&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>当然字节序不能完全靠处理器来判断,因为有些处理器可能既支持大端字节序又支持小端字节序\\n最好用的方式还是用个程序跑一跑,实践是检验整理的唯一标准.</p>\\n<div class=\\"language-cpp line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">cpp</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">#include</span><span style=\\"color:#032F62\\"> &#x3C;stdio.h></span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">int</span><span style=\\"color:#6F42C1\\"> main</span><span style=\\"color:#24292E\\">()</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">{</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    unsigned</span><span style=\\"color:#D73A49\\"> int</span><span style=\\"color:#24292E\\"> x </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#D73A49\\"> 0x</span><span style=\\"color:#005CC5\\">12345678</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    char</span><span style=\\"color:#D73A49\\"> *</span><span style=\\"color:#24292E\\">p </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">char</span><span style=\\"color:#D73A49\\"> *</span><span style=\\"color:#24292E\\">)</span><span style=\\"color:#D73A49\\">&#x26;</span><span style=\\"color:#24292E\\">x;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    int</span><span style=\\"color:#24292E\\"> i;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    for</span><span style=\\"color:#24292E\\"> (i </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">; i </span><span style=\\"color:#D73A49\\">&#x3C;</span><span style=\\"color:#D73A49\\"> sizeof</span><span style=\\"color:#24292E\\">(x); i</span><span style=\\"color:#D73A49\\">++</span><span style=\\"color:#24292E\\">){</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">        printf</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">\\"</span><span style=\\"color:#005CC5\\">%.2x</span><span style=\\"color:#032F62\\"> \\"</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#24292E\\">p</span><span style=\\"color:#D73A49\\">++</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    printf</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">\\"</span><span style=\\"color:#005CC5\\">\\\\n</span><span style=\\"color:#032F62\\">\\"</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br></div></div><p>上面的一段 C 程序就可以检验字节序,<br>\\n如果输出是：12 34 56 78,那么 CPU 是大端字节序.<br>\\n如果输出时：78 56 34 12,那么 CPU 是小端字节序.<br>\\n输出证明,大端字节序更适合人类阅读.</p>\\n<h2 id=\\"涉及字节序的问题\\" tabindex=\\"-1\\">涉及字节序的问题 <a class=\\"header-anchor\\" href=\\"#涉及字节序的问题\\" aria-label=\\"Permalink to &quot;涉及字节序的问题&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>谈到字节序问题,是因为网络编程的时候如果双方的字节序不一样肯定会出问题的.本人在交叉编译学校的校园网程序的时候就是遇到了这个问题,因为字节序的不同,导致发送的数据包是相反的.后来在老师的点拨下才得以解决.</p>\\n"}]},"relativePath":"page/32/index.md","filePath":"page/[page].md"}`),l={name:"page/32/index.md"};function p(e,o,r,t,c,i){return a(),n("div")}const u=s(l,[["render",p]]);export{b as __pageData,u as default};
